// The Projects screen's page modes (#1876) — a pure, React-free data module so both the screen
// (`features/planner/index.tsx`) and its tests share one source of truth. Drives the shared
// <Screen> tab bar: each mode can be torn off into its own window (#430/#463).

import type { TabItem } from "@/shared/ui/layouts/TabBar";

export const PROJECT_MODES: TabItem[] = [
  { id: "projects",   label: "Projects",    hint: "plan a project" },
  // THE FIVE GRAPHS LEFT (`five-graphs-become-rail-workspaces`). Teams, Components (the tab id was
  // "designs", the internal feature name), Algorithms, Sounds and Data were each folded in here
  // because "a single read-only page needs no rail destination of its own". That reasoning is
  // reversed: the graphs ARE the app, so each is a rail destination again and none is a Planner tab.
  //
  // The Planner is left with ONE page. The tab strip renders a single tab, which is the honest
  // picture — the Planner plans projects, and everything else it had accumulated has its own home.
  // A persisted page-mode naming any of the departed tabs is forwarded by `migrateGraphPage`.
  //
  // Removing them could not happen until the studio docks followed (`studio-docks-follow-the-graphs`):
  // `studioPageShowing` read `projectsPageMode`, and deleting the tabs first would have left every
  // studio's dock reporting false — which, because `openStudio` is the lazy launch, means the
  // designer, librarians, architect and sound-designer would never start at all.
];

